// Declarations shared by our own source files (src/main, src/game).
#ifndef KIGOLD_DECLS_H
#define KIGOLD_DECLS_H

#include <cstdint>
#include <memory>

#include "recomp.h"
#include "ultramodern/ultra64.h"
#include "ultramodern/ultramodern.hpp"
#include "librecomp/rsp.hpp"

// The recompiled game's first function. Generated by N64Recomp (RecompiledFuncs/).
extern "C" void recomp_entrypoint(uint8_t* rdram, recomp_context* ctx);

// The translated audio microcode. Generated by RSPRecomp (rsp/kigold_audio.cpp).
RspExitReason kigold_audio_ucode(uint8_t* rdram, uint32_t ucode_addr);

namespace kigold {
    // Tells the runtime where each block of recompiled code lives in the ROM and in
    // RAM. In src/main/register_overlays.cpp.
    void register_overlays();

    // A generated function, found from an address in its compiled PC code.
    struct GeneratedFunc {
        uint32_t vram;        // the function's N64 address
        uint32_t section;     // its section in the generated section table
        uint32_t host_offset; // how far the PC address is past the function's start
        bool shared;          // the linker merged several generated functions into this code
    };
    // Finds the generated function a PC code address lies in. False if it is not
    // in generated code. In src/main/register_overlays.cpp.
    bool find_generated_function(uintptr_t host_address, GeneratedFunc& out);

    // Crash reporter, in src/main/crash_reporter.cpp. note_rdram tells it where the
    // game's memory is, so it can turn a PC memory address into an N64 address.
    void install_crash_reporter();
    void note_rdram(uint8_t* rdram);
    // Where the game's memory is, or nullptr if nobody has told us yet.
    uint8_t* known_rdram();
    // Like find_generated_function, but only true if the address really lies in
    // that function's PC code (on Windows, checked against the unwind table).
    bool find_game_function(uintptr_t host_address, GeneratedFunc& out);
    // Name of a section of the generated section table: boot, stream1, 2 or 3.
    const char* section_name(uint32_t section);

    // Heartbeat, in src/main/heartbeat.cpp. Off unless the environment variable
    // KIGOLD_HEARTBEAT is set. The count_ and note_ calls do nothing while it is off.
    void start_heartbeat();
    void count_video_tick();
    void count_audio_task();
    void count_inflate();
    // Called by the runtime once for each thread the game creates, on that thread.
    void note_game_thread(const OSThread* thread);
    // Wraps the renderer so graphics tasks can be counted. Returns it unchanged
    // while the heartbeat is off.
    std::unique_ptr<ultramodern::renderer::RendererContext> count_graphics_tasks(
        std::unique_ptr<ultramodern::renderer::RendererContext> renderer);
}

#endif
